-- MySQL versions of the SQL Server stored procedures.

DELIMITER //

CREATE PROCEDURE `ten_most_expensive_products`()
BEGIN
    SELECT product_name AS ten_most_expensive_products, unit_price
    FROM products
    ORDER BY unit_price DESC
    LIMIT 10;
END//

CREATE PROCEDURE `employee_sales_by_country`(IN p_beginning_date DATETIME, IN p_ending_date DATETIME)
BEGIN
    SELECT employees.country, employees.last_name, employees.first_name,
           orders.shipped_date, orders.order_id, `order_subtotals`.subtotal AS sale_amount
    FROM employees
    INNER JOIN orders ON employees.employee_id = orders.employee_id
    INNER JOIN `order_subtotals` ON orders.order_id = `order_subtotals`.order_id
    WHERE orders.shipped_date BETWEEN p_beginning_date AND p_ending_date;
END//

CREATE PROCEDURE `sales_by_year`(IN p_beginning_date DATETIME, IN p_ending_date DATETIME)
BEGIN
    SELECT orders.shipped_date, orders.order_id, `order_subtotals`.subtotal,
           YEAR(orders.shipped_date) AS `year`
    FROM orders
    INNER JOIN `order_subtotals` ON orders.order_id = `order_subtotals`.order_id
    WHERE orders.shipped_date BETWEEN p_beginning_date AND p_ending_date;
END//

CREATE PROCEDURE cust_orders_detail(IN p_order_id INT)
BEGIN
    SELECT P.product_name, ROUND(od.unit_price, 2) AS unit_price, od.quantity,
           CAST(od.discount * 100 AS SIGNED) AS discount,
           ROUND(CAST(od.quantity * (1 - od.discount) * od.unit_price AS DECIMAL(19,4)), 2) AS extended_price
    FROM products P
    INNER JOIN `order_details` od ON od.product_id = P.product_id
    WHERE od.order_id = p_order_id;
END//

CREATE PROCEDURE cust_orders_orders(IN p_customer_id CHAR(5))
BEGIN
    SELECT order_id, order_date, required_date, shipped_date
    FROM orders
    WHERE customer_id = p_customer_id
    ORDER BY order_id;
END//

CREATE PROCEDURE cust_order_hist(IN p_customer_id CHAR(5))
BEGIN
    SELECT P.product_name, SUM(OD.quantity) AS total
    FROM products P
    INNER JOIN `order_details` OD ON OD.product_id = P.product_id
    INNER JOIN orders O ON O.order_id = OD.order_id
    WHERE O.customer_id = p_customer_id
    GROUP BY P.product_name;
END//

CREATE PROCEDURE sales_by_category(IN p_category_name VARCHAR(15), IN p_ord_year VARCHAR(4))
BEGIN
    IF p_ord_year IS NULL OR p_ord_year NOT IN ('1996', '1997', '1998') THEN
        SET p_ord_year = '1998';
    END IF;
    SELECT P.product_name,
           ROUND(SUM(CAST(OD.quantity * (1 - OD.discount) * OD.unit_price AS DECIMAL(14,2))), 0) AS total_purchase
    FROM `order_details` OD
    INNER JOIN orders O ON OD.order_id = O.order_id
    INNER JOIN products P ON OD.product_id = P.product_id
    INNER JOIN categories C ON P.category_id = C.category_id
    WHERE C.category_name = p_category_name
      AND DATE_FORMAT(O.order_date, '%Y') = p_ord_year
    GROUP BY P.product_name
    ORDER BY P.product_name;
END//

DELIMITER ;
